// Types for the bridge hardening cases in StreamingAssets/luaBridgeHardening.lua
// (docs/research/bridge-audit.md, items 2, 5, 6, 7, 9, 10, 11 and 12). The
// bridge checks (items 2, 5 and 7) follow the build type, the rest are opt-in
// C# defines (docs/design/bridge-hardening.md); each case checks the behaviour
// of the build the suite was compiled as (run_managed.py --define), so it passes
// with and without them. Build xLua with the same defines.
// <xlua-preset> generated by Tools/presets.py from docs/design/presets.md; do not edit
#if XLUA_PRESET_MINIMAL
#define XLUA_NO_STREAMING_ASSETS_LOADER
#define XLUA_NO_SIGNATURE_LOADER
#define XLUA_NO_TEMPLATE
#if !XLUA_UTIL
#define XLUA_NO_UTIL
#endif
#define XLUA_NO_PROFILER
#define XLUA_NO_LOAD_ASSEMBLY
#define XLUA_LOCK_METATABLES
#define XLUA_RESTRICT_GETMETATABLE
#define XLUA_LOCK_XLUA_TABLE
#define XLUA_RESTRICT_PRIVATE_ACCESS
#define XLUA_REDUCED_DEBUG
#if !XLUA_REFLECTION
#define XLUA_NO_REFLECTION
#endif
#if !XLUA_NO_GCM
#define GEN_CODE_MINIMIZE
#endif
#endif
#if (UNITY_EDITOR || DEVELOPMENT_BUILD || XLUA_GENERAL) && !XLUA_NO_BRIDGE_CHECKS
#define XLUA_BRIDGE_CHECKS
#endif
// </xlua-preset>
using System;
using System.Reflection;
using System.Runtime.InteropServices;
using XLua;

namespace BridgeHardening
{
    [LuaCallCSharp]
    public class Probe
    {
        public int Value;

        public Probe(int value)
        {
            Value = value;
        }

        public int GetValue()
        {
            return Value;
        }

        // Pushes this object again, which goes through the userdata cache.
        public Probe Self()
        {
            return this;
        }

        public static Probe Make(int value)
        {
            return new Probe(value);
        }

        public override string ToString()
        {
            return "Probe" + Value;
        }

        static int Secret()
        {
            return 42;
        }

        static int secretField = 7;

        public static T Echo<T>(T value)
        {
            return value;
        }

        static T Hidden<T>(T value)
        {
            return value;
        }

        // MethodBase values for xlua.tofunction.
        public static MethodInfo PublicMethod()
        {
            return typeof(Probe).GetMethod("Make");
        }

        public static MethodInfo SecretMethod()
        {
            return typeof(Probe).GetMethod("Secret", BindingFlags.NonPublic | BindingFlags.Static);
        }
    }

    // The defines the suite was built with.
