        // Editor, Development Builds and XLUA_GENERAL, which runs this suite;
        // off with XLUA_NO_BRIDGE_CHECKS, as in a release player).
        public static bool BridgeChecks()
        {
#if XLUA_BRIDGE_CHECKS
            return true;
#else
            return false;
#endif
