            return true;
#else
            return false;
#endif
        }
    }

    // C functions that build userdata a script cannot otherwise make: a block that
    // is not a C# object but carries the bytes the bridge reads from one.
    public static class Natives
    {
        // forge(obj): a full userdata without a metatable whose first int is the
        // object pool index of the C# object obj, as a foreign userdata (a socket
        // holding a small file descriptor, say) may have.
        public static XLua.LuaDLL.lua_CSFunction Forger()
        {
            return Forge;
        }

        [MonoPInvokeCallback(typeof(XLua.LuaDLL.lua_CSFunction))]
        static int Forge(IntPtr L)
        {
            int index = XLua.LuaDLL.Bridge.xlua_tocsobj_safe(L, 1);
            IntPtr block = XLua.LuaDLL.Bridge.xlua_pushstruct(L, 0, -1); // registry[-1] is nil: no metatable
            Marshal.WriteInt32(block, index);
            return 1;
        }

        // fake(size): a full userdata without a metatable that has the struct header
        // (fake_id -1, len size) and size zero bytes, the only thing the
        // xlua.genaccessor accessors check without the bridge checks.
        public static XLua.LuaDLL.lua_CSFunction FakeStruct()
        {
            return Fake;
        }

        [MonoPInvokeCallback(typeof(XLua.LuaDLL.lua_CSFunction))]
        static int Fake(IntPtr L)
        {
            int size = XLua.LuaDLL.Bridge.xlua_tointeger(L, 1);
            IntPtr block = XLua.LuaDLL.Bridge.xlua_pushstruct(L, (uint)size, -1);
            for (int i = 0; i < size; i++)
            {
                Marshal.WriteByte(block, 8 + i, 0);
            }
            return 1;
        }

        // index(obj): the object pool index of a C# object, or -1.
        public static XLua.LuaDLL.lua_CSFunction Indexer()
        {
            return Index;
        }

        [MonoPInvokeCallback(typeof(XLua.LuaDLL.lua_CSFunction))]
        static int Index(IntPtr L)
        {
            XLua.LuaDLL.Bridge.xlua_pushinteger(L, XLua.LuaDLL.Bridge.xlua_tocsobj_safe(L, 1));
            return 1;
        }

        static readonly System.Collections.Generic.List<IntPtr> pointers = new System.Collections.Generic.List<IntPtr>();

        // A pointer to unmanaged memory holding the int index; Lua gets an IntPtr
        // as a light userdata.
        public static IntPtr IndexPointer(int index)
        {
            IntPtr p = Marshal.AllocHGlobal(sizeof(int));
            Marshal.WriteInt32(p, index);
            pointers.Add(p);
            return p;
        }

        public static void FreePointers()
        {
            foreach (IntPtr p in pointers)
            {
                Marshal.FreeHGlobal(p);
            }
            pointers.Clear();
        }
    }
}
